 // ══════════════════════════════════════════════════════════════
 // POST /api/academy-admin/counsel  { student_id }
 //
 // 학원장 상담용 AI 카드 생성.
 //   - 학생의 계획·성적·이행률·취약과목을 종합해
 //     (1) 상담 3줄 요약 (2) 학부모에게 할 말 (3) 다음 한 달 권장 방향
 //   을 생성한다. 학원장이 화면을 해석할 필요 없이 그대로 읽으며 상담.
 //
 // 권한: 해당 학생이 소속된 학원의 admin만. (학부모·학생 거부)
 // ══════════════════════════════════════════════════════════════
 import { NextRequest, NextResponse } from 'next/server';
 import { z } from 'zod';
 import { anthropic, MODELS } from '@/lib/anthropic';
 import { supabaseAdmin } from '@/lib/supabase';
 import { requireUser, AuthError, authErrorResponse, assertAcademyAdmin } from '@/lib/auth';
 import { rateLimit } from '@/lib/rate-limit';
 import { gradeContext } from '@/lib/grade-system';
 import {
   gradeSystemForType,
   targetGradeFor,
   buildSubjectGrades,
 } from '@/lib/goal-grade';
-import { goalUniversityLabel } from '@/lib/grade-system';
+import { goalUniversityLabel, GRADE_SYSTEM_LABEL, type GradeSystem } from '@/lib/grade-system';

 const RequestSchema = z.object({
   student_id: z.string().min(1),
 });

 const SYSTEM_PROMPT = `당신은 대치동 21년 경력의 입시 컨설턴트입니다. 학원장이 학생·학부모 상담 직전에 펼쳐 읽을 "상담 브리핑 카드"를 작성합니다.

 # 핵심 원칙
 - 학원장이 화면을 해석할 필요 없이, 적힌 문장을 그대로 말하며 상담할 수 있어야 합니다.
 - 데이터(이행률·등급·약점)를 나열하지 말고, 그 데이터가 의미하는 "결론과 방향"을 말하세요.
 - 모든 권장에는 근거가 한 줄에 녹아 있어야 합니다("이 시기에는", "이 등급대는", "이 약점이라면").
 - 반드시 존댓말. 단정적이되 정중한 컨설턴트 톤("~이 우선입니다", "~을 권장드립니다", "~이 안전합니다").
 - 막연한 표현 금지("열심히", "꾸준히"). 과목·교재·시기를 구체적으로.
 - 학년 제도를 정확히 반영: 고1·2는 내신 5등급제·고교학점제·2028 통합형 수능(수능 D-day 언급 금지, 학기 흐름으로), 고3·N수는 수능 중심.
 - 마크다운 강조(별표·백틱) 금지. 평문으로.`;

 export async function POST(req: NextRequest) {
   try {
     const user = await requireUser();

     const rl = rateLimit(`counsel:${user.id}`, 20, 60_000);
     if (!rl.ok) {
       return NextResponse.json(
         { error: `상담 카드 생성이 너무 잦습니다. ${rl.retryAfterSec}초 후 다시 시도해 주세요.` },
         { status: 429, headers: { 'Retry-After': String(rl.retryAfterSec) } }
       );
     }

     const parsed = RequestSchema.safeParse(await req.json());
     if (!parsed.success) {
       return NextResponse.json({ error: '학생 ID 필수' }, { status: 400 });
     }
     const { student_id } = parsed.data;

     // ── 학생 + 학원 admin 권한 검증 ──
     const { data: student } = await supabaseAdmin
       .from('students')
       .select('id, name, type, exam_type, target_university, academy_id')
       .eq('id', student_id)
       .maybeSingle();

     if (!student) throw new AuthError(404, '학생을 찾을 수 없습니다');
     if (!student.academy_id) throw new AuthError(403, '학원에 소속되지 않은 학생');

     await assertAcademyAdmin(user.id, student.academy_id as string);

     // ── 상담 재료 수집 ──
     const today = new Date().toISOString().slice(0, 10);
     const fourWeeksAgo = new Date(Date.now() - 28 * 86400000).toISOString().slice(0, 10);

     const [{ data: profile }, { data: plan }, { data: gradeRows }, { data: tasks }] =
       await Promise.all([
         supabaseAdmin
           .from('student_profiles')
           .select('focus_minutes, math_subject, kor_subject, science_subject_1, science_subject_2, study_style, weakness, goal_university')
           .eq('student_id', student_id)
           .maybeSingle(),
         supabaseAdmin
           .from('study_plans')
           .select('plan_type, ai_advice, content_json, created_at')
           .eq('student_id', student_id)
           .order('created_at', { ascending: false })
           .limit(1)
           .maybeSingle(),
         supabaseAdmin
           .from('grades')
-          .select('subject, grade, exam_date')
+          // grade_system(#208) — 기록 시점 등급제. 없으면 진급 직후 고2 내신(5등급제)이
+          // 9등급제 기준으로 갭·추세에 들어가 상담 프롬프트가 틀린 전제로 시작한다.
+          .select('subject, grade, exam_date, grade_system')
           .eq('student_id', student_id)
           .order('exam_date', { ascending: false })
           .limit(60),
         supabaseAdmin
           .from('daily_tasks')
           .select('completed')
           .eq('student_id', student_id)
           .eq('source', 'ai')
           .gte('date', fourWeeksAgo)
           .lte('date', today),
       ]);

     const gctx = gradeContext(student.type ?? 'high3');
     const gradeSystem = gradeSystemForType(student.type ?? 'high3');
     const targetGrade = targetGradeFor(profile?.goal_university, gradeSystem);
     const subjectGrades = buildSubjectGrades(
-      (gradeRows ?? []) as Array<{ subject: string; grade: number; exam_date: string }>,
-      targetGrade
+      (gradeRows ?? []) as Array<{
+        subject: string;
+        grade: number;
+        exam_date: string;
+        grade_system?: GradeSystem | null;
+      }>,
+      targetGrade,
+      gradeSystem
     );

     const taskList = (tasks ?? []) as Array<{ completed: boolean }>;
     const total = taskList.length;
     const done = taskList.filter((t) => t.completed).length;
     const rate4w = total > 0 ? Math.round((done / total) * 100) : 0;

     const planContent = (plan?.content_json ?? {}) as Record<string, unknown>;
     const milestones = (planContent.milestones as string[] | undefined) ?? [];
     const planSubjects = (planContent.subjects as Array<{ subject?: string; priority?: string; recommended_books?: string[] }> | undefined) ?? [];

     const gradeText =
       subjectGrades.length > 0
         ? subjectGrades
             .map((s) => {
               const gapStr = s.gap != null ? (s.gap > 0 ? `목표대비 +${s.gap}` : '목표도달') : '';
               const trendStr = s.delta != null ? (s.delta < 0 ? '↑상승' : s.delta > 0 ? '↓하락' : '유지') : '';
-              return `${s.subject} ${s.latest}등급${trendStr ? ` (${trendStr})` : ''}${gapStr ? ` [${gapStr}]` : ''}`;
+              // 현재 등급제와 다른 성적은 등급제를 병기한다(#208). 병기가 없으면 모델이
+              // 위 '학년·제도' 줄의 등급제로 이 숫자를 읽어 상담 방향이 틀어진다.
+              // 갭·추세는 buildSubjectGrades가 이미 null로 비워 교차 비교를 막았다.
+              const sysStr = s.crossSystem ? `(${GRADE_SYSTEM_LABEL[s.system]})` : '';
+              return `${s.subject} ${s.latest}등급${sysStr}${trendStr ? ` (${trendStr})` : ''}${gapStr ? ` [${gapStr}]` : ''}`;
             })
             .join(', ')
         : '성적 데이터 없음';

     const userPrompt = `[학생]
 - 이름: ${student.name ?? '학생'}
 - 학년·제도: ${gctx.fullLabel}
 - 목표 대학: ${goalUniversityLabel(profile?.goal_university)}${targetGrade != null ? ` (참고 안정권 ${targetGrade}등급선)` : ''}
 - 선택/주요 과목: 수학 ${profile?.math_subject ?? '-'}, 국어 ${profile?.kor_subject ?? '-'}, 탐구 ${profile?.science_subject_1 ?? '-'}/${profile?.science_subject_2 ?? '-'}
 - 약점 단원: ${(profile?.weakness ?? []).join(', ') || '미입력'}
 - 집중 시간: ${profile?.focus_minutes ?? '-'}분

 [성적(과목별 최신 등급·추세·목표갭)]
 ${gradeText}

 [학습 이행]
 - 최근 4주 이행률: ${rate4w}% (${done}/${total})

 [현재 계획]
 - 최근 계획 종류: ${plan?.plan_type ?? '없음'}
 - 과목 우선순위: ${planSubjects.map((s) => `${s.subject ?? ''}(${s.priority ?? '-'})`).join(', ') || '-'}
 - 마일스톤: ${milestones.slice(0, 4).join(' / ') || '-'}
 - 최근 AI 코칭: ${plan?.ai_advice ?? '-'}

 [요청]
 위 학생의 상담 브리핑을 submit_counsel_card 도구로 작성하세요.`;

     const response = await anthropic.messages.create({
       model: MODELS.SMART,
       max_tokens: 1200,
       system: [{ type: 'text', text: SYSTEM_PROMPT, cache_control: { type: 'ephemeral' } }],
       tools: [
         {
           name: 'submit_counsel_card',
           description: '학원장이 상담 중 그대로 읽을 브리핑 카드.',
           input_schema: {
             type: 'object',
             properties: {
               headline: {
                 type: 'string',
                 description: '이 학생의 현재 상태를 한 문장으로 압축 (예: "내신 안정권이나 수학 방향 전환이 시급한 시점").',
               },
               summary: {
                 type: 'array',
                 items: { type: 'string' },
                 description: '상담 핵심 3줄. 각 줄은 결론+근거가 녹은 한 문장. 데이터 나열 금지.',
               },
               parent_message: {
                 type: 'string',
                 description: '학부모에게 그대로 전할 멘트 2~3문장. 안심+방향 제시. 존댓말.',
               },
               direction: {
                 type: 'string',
                 description: '다음 한 달 권장 방향 2~3문장. 과목·교재·시기 구체적. 학년 제도 반영.',
               },
               talking_points: {
                 type: 'array',
                 items: { type: 'string' },
                 description: '상담 중 짚을 질문·확인 포인트 2~3개 (예: "수학 인강 주 몇 회 수강 중인지 확인").',
               },
             },
             required: ['headline', 'summary', 'parent_message', 'direction'],
           },
         },
       ],
       tool_choice: { type: 'tool', name: 'submit_counsel_card' },
       messages: [{ role: 'user', content: userPrompt }],
     });

     const toolUse = response.content.find((c) => c.type === 'tool_use');
     const card =
       toolUse && toolUse.type === 'tool_use'
         ? (toolUse.input as Record<string, unknown>)
         : { headline: '', summary: [], parent_message: '생성 실패', direction: '', talking_points: [] };

     return NextResponse.json({ card, generated_at: new Date().toISOString() });
   } catch (e) {
     return authErrorResponse(e);
   }
 }
diff --git a/app/api/academy-admin/grades/route.ts b/app/api/academy-admin/grades/route.ts
index fb289a85..e27ab0a0 100644
--- a/app/api/academy-admin/grades/route.ts
+++ b/app/api/academy-admin/grades/route.ts
@@ -1,137 +1,136 @@
 // ══════════════════════════════════════════════════════════════
 // POST /api/academy-admin/grades
 //   { student_id, exam_name, exam_date:'YYYY-MM-DD', grades:{[subject]:number} }
 //
 // 운영자(학원장)가 학생 대신 모의고사·내신 성적을 입력한다.
 // "첫 등원 시 성적표 입력 → 로드맵" 운영자 플로우의 입력 단계.
 // 성적이 들어가면 다음 계획 생성 시 자동 반영(_input_fp 변경).
 //
 // 권한: 해당 학생이 소속된 학원의 admin만.
 // ══════════════════════════════════════════════════════════════
 import { NextRequest, NextResponse } from 'next/server';
 import { z } from 'zod';
 import { supabaseAdmin } from '@/lib/supabase';
 import { requireUser, AuthError, authErrorResponse, assertAcademyAdmin } from '@/lib/auth';
 import { sanitizeGradeSubjectScores } from '@/lib/grade-subject-sanitization';
+import { stampGradeSystem, gradeRangeError } from '@/lib/grade-provenance';
+import type { StudentType } from '@/lib/grade-system';

 // 과목별 상세 점수 — 등급/원점수/백분위/표준점수 + 내신(성취도·환산점수·석차) (모두 선택, 최소 1개 필요)
 const SubjectScore = z.object({
   grade: z.number().int().min(1).max(9).optional(),
   raw_score: z.number().int().min(0).max(200).optional(),
   percentile: z.number().int().min(0).max(100).optional(),
   standard_score: z.number().int().min(0).max(300).optional(),
   achievement: z.enum(['A', 'B', 'C', 'D', 'E']).optional(),
   converted_score: z.number().min(0).max(200).optional(),
   rank: z.number().int().min(1).max(100000).optional(),
   rank_total: z.number().int().min(1).max(100000).optional(),
   report_type: z.enum(['mock', 'naesin', 'suneung']).optional(),
   // p90 — 내신 rigor: 과목평균(5·9등급제 공통)·표준편차(9등급제 전용)
   subject_average: z.number().min(0).max(100).optional(),
   std_dev: z.number().min(0).max(50).optional(),
 });

 const PostSchema = z.object({
   student_id: z.string().min(1),
   exam_name: z.string().min(1).max(60),
   exam_date: z.string().regex(/^\d{4}-\d{2}-\d{2}$/),
   // 시험(성적표) 단위 학년·학기 — 한 시험의 모든 과목 행이 같은 값을 공유(둘 다 optional=미지정)
   grade_level: z.enum(['high1', 'high2', 'high3']).optional(),
   semester: z.union([z.literal(1), z.literal(2)]).optional(),
   // 신규: 과목별 상세 점수 (성적표 OCR/직접입력)
   scores: z.record(z.string(), SubjectScore).optional(),
   // 레거시: 과목별 등급만 (구버전 클라이언트 호환)
   grades: z.record(z.string(), z.number().int().min(1).max(9)).optional(),
 }).refine((d) => d.semester == null || d.grade_level != null, {
   // 학기만 있고 학년이 없으면 academicRank·semesterLabel이 모두 null → "학기 미지정"으로 조용히 증발.
   // 학기 지정은 학년 지정을 전제로 강제한다.
   message: '학기를 지정하려면 학년도 함께 선택해야 합니다.',
   path: ['semester'],
 });

 export async function POST(req: NextRequest) {
   try {
     const user = await requireUser();
     const parsed = PostSchema.safeParse(await req.json());
     if (!parsed.success) {
       return NextResponse.json({ error: '입력 형식 오류' }, { status: 400 });
     }
     const { student_id, exam_name, exam_date, grade_level, semester } = parsed.data;

     // 신규(scores) 우선, 없으면 레거시(grades) → scores 형태로 정규화
     const rawScores: Record<string, z.infer<typeof SubjectScore>> =
       parsed.data.scores ??
       Object.fromEntries(
         Object.entries(parsed.data.grades ?? {}).map(([s, g]) => [s, { grade: g }])
       );

     // 학원 admin 권한 검증
     const { data: student } = await supabaseAdmin
       .from('students')
       .select('academy_id, type')
       .eq('id', student_id)
       .maybeSingle();
     if (!student) throw new AuthError(404, '학생을 찾을 수 없습니다');
     if (!student.academy_id) throw new AuthError(403, '학원에 소속되지 않은 학생');

     await assertAcademyAdmin(user.id, student.academy_id as string);

     const sanitized = await sanitizeGradeSubjectScores(student.type, rawScores);
     if (!sanitized.ok) {
       return NextResponse.json({ error: sanitized.error }, { status: sanitized.status });
     }
     const entries = Object.entries(sanitized.scores).filter(
       ([, v]) =>
         v.grade != null || v.raw_score != null || v.percentile != null || v.standard_score != null ||
         v.achievement != null || v.converted_score != null || v.rank != null ||
         v.subject_average != null
     );
     if (entries.length === 0) {
       return NextResponse.json({ error: '최소 한 과목의 성적을 입력해주세요.' }, { status: 400 });
     }

     // 등급 범위: 내신은 고1·2(5등급제) 1~5, 고3·N수(9등급제) 1~9.
     // 모의고사(학평·모평)·수능은 학년 무관 9등급제 — 5등급 캡을 적용하면 고1·2
     // 입력이 잘못 거부된다. 성적표 종류 선택 UI도 mock·naesin·suneung을 모두 전송한다.
-    const maxNaesinG = student.type === 'high1' || student.type === 'high2' ? 5 : 9;
+    // 판정은 grade-provenance로 단일화했다(#208) — 학생 자가 입력 라우트와 같은 규칙.
+    const studentType = student.type as StudentType;
     for (const [, v] of entries) {
-      const isNineGradeReport = v.report_type === 'mock' || v.report_type === 'suneung';
-      const maxG = isNineGradeReport ? 9 : maxNaesinG;
-      if (v.grade != null && (v.grade < 1 || v.grade > maxG)) {
-        return NextResponse.json(
-          { error: `${isNineGradeReport ? '모의고사·수능' : '이 학생의 내신'}은 ${maxG}등급제입니다. 1~${maxG} 범위로 입력하세요.` },
-          { status: 400 }
-        );
-      }
+      const rangeError = gradeRangeError(v.grade, v.report_type ?? null, studentType);
+      if (rangeError) return NextResponse.json({ error: rangeError }, { status: 400 });
     }

     const rows = entries.map(([subject, v]) => ({
       student_id,
       exam_name,
       subject,
       grade: v.grade ?? null,
       raw_score: v.raw_score ?? null,
       percentile: v.percentile ?? null,
       standard_score: v.standard_score ?? null,
       achievement: v.achievement ?? null,
       converted_score: v.converted_score ?? null,
       rank: v.rank ?? null,
       rank_total: v.rank_total ?? null,
       report_type: v.report_type ?? null,
       subject_average: v.subject_average ?? null,
       std_dev: v.std_dev ?? null,
