 // ── 입력 지문(fingerprint) ─────────────────────────────────────
 // 계획 캐시는 "수강 강의 변경" 외에는 무효화되지 않아, 학생의 이름·성적·
 // 프로필·D-day 페이즈가 바뀌어도 옛 계획 본문(이름·등급·D-day)이 그대로
 // 남는 문제가 있었다. 아래 지문이 달라지면 캐시를 버리고 재생성한다.
 function stableHash(s: string): string {
   let h = 5381;
   for (let i = 0; i < s.length; i++) h = ((h << 5) + h + s.charCodeAt(i)) | 0;
   return (h >>> 0).toString(36);
 }

