+    // 처방이 달라진다. 키에 없으면 p143 백필로 provenance가 생기거나 등급제가 정정돼도
+    // 지문이 그대로라 **잘못된 해석으로 만든 옛 계획이 계속 반환된다**(시간 만료도 없다).
+    .map(
+      (g) =>
+        `${g.subject}:${g.grade}:${g.grade_level ?? ''}-${g.semester ?? ''}:${g.grade_system ?? ''}`
+    )
     .sort()
     .join(',');
 }
