 42	/** 전환을 실행한 주체의 역할. assertStudentAccess를 통과한 뒤에만 호출한다. */
 43	async function resolveActorRole(userId: string, ownerUserId: string | null): Promise<string> {
 44	  if (ownerUserId && ownerUserId === userId) return 'student';
 45	  const role = await getUserRole(userId);
 46	  if (role === 'admin' || role === 'teacher') return role;
 47	  // 본인도 전역 운영자도 아닌데 통과했다면 소속 학원의 active 학원장이다.
 48	  return 'academy_admin';
 49	}
