 95	/** 오늘 일간 계획이 옛 학년 기준으로 캐시돼 있는가. */
 96	async function isDailyPlanStale(studentId: string): Promise<boolean> {
 97	  const { data } = await supabaseAdmin
 98	    .from('study_plans')
 99	    .select('content_json')
100	    .eq('student_id', studentId)
101	    .eq('plan_type', 'daily')
102	    .order('created_at', { ascending: false })
103	    .limit(1)
104	    .maybeSingle();
105	  const cachedDate = (data?.content_json as { date?: string } | null)?.date;
106	  return cachedDate === todayKST();
107	}
