111	// ──────────────────────────────────────────────
112	export async function GET(req: NextRequest): Promise<NextResponse> {
113	  try {
114	    const user = await requireUser();
115	    const requested = req.nextUrl.searchParams.get('student_id');
116	    const studentId = requested ?? (await findStudentId(user.id));
117	    if (requested) await assertStudentAccess(user.id, studentId, 'read');
118	
119	    const { data, error } = await supabaseAdmin
120	      .from('student_type_transitions')
121	      .select('*')
122	      .eq('student_id', studentId)
123	      .order('created_at', { ascending: false })
124	      .limit(50);
125	    if (error) {
126	      console.error('[promotion GET] transitions select error:', error);
127	      return NextResponse.json({ error: '이력 조회 실패' }, { status: 500 });
128	    }
129	
130	    const transitions = (data ?? []) as StudentTypeTransition[];
131	    return NextResponse.json({
132	      transitions: transitions.map((t) => ({
133	        ...t,
134	        description: describeTransition(t.from_type, t.to_type, t.kind),
135	      })),
136	      // 가장 최근 전환은 되돌릴 수 있다(그 이전 것은 중간 상태를 건너뛰게 되므로 정정으로 처리).
137	      revertable: transitions[0]
138	        ? { transition_id: transitions[0].id, to_type: transitions[0].from_type }
139	        : null,
140	    });
141	  } catch (e) {
142	    return authErrorResponse(e);
143	  }
144	}
