    96	    // 입력이 잘못 거부된다. 성적표 종류 선택 UI도 mock·naesin·suneung을 모두 전송한다.
    97	    // 판정은 grade-provenance로 단일화했다(#208) — 학생 자가 입력 라우트와 같은 규칙.
    98	    const studentType = student.type as StudentType;
    99	    for (const [, v] of entries) {
   100	      const rangeError = gradeRangeError(v.grade, v.report_type ?? null, studentType);
   101	      if (rangeError) return NextResponse.json({ error: rangeError }, { status: 400 });
   102	    }
   103	
   104	    const rows = entries.map(([subject, v]) => ({
   105	      student_id,
   106	      exam_name,
   107	      subject,
   108	      grade: v.grade ?? null,
   109	      raw_score: v.raw_score ?? null,
   110	      percentile: v.percentile ?? null,
   111	      standard_score: v.standard_score ?? null,
   112	      achievement: v.achievement ?? null,
   113	      converted_score: v.converted_score ?? null,
   114	      rank: v.rank ?? null,
   115	      rank_total: v.rank_total ?? null,
   116	      report_type: v.report_type ?? null,
   117	      subject_average: v.subject_average ?? null,
   118	      std_dev: v.std_dev ?? null,
   119	      grade_level: grade_level ?? null,
   120	      semester: semester ?? null,
   121	      // 기록 시점 등급제 각인(p143 / #208) — 진급 후 재해석 방지용 출처 보존.
   122	      grade_system: stampGradeSystem(v.report_type ?? null, studentType),
   123	      exam_date,
   124	    }));
   125	
   126	    const { error } = await supabaseAdmin.from('grades').insert(rows);
   127	    if (error) {
   128	      console.error('[academy-admin/grades POST] insert error:', error);
   129	      throw new AuthError(500, '저장 실패');
   130	    }
   131	
   132	    return NextResponse.json({ ok: true, inserted: rows.length });
   133	  } catch (e) {
   134	    return authErrorResponse(e);
   135	  }
   136	}

