    67	
    68	  const kind = target ? classifyTransition(current, target) : null;
    69	  const systemChange = target ? gradeSystemChange(current, target) : null;
    70	  const needsReason = kind ? transitionRequiresReason(kind) : false;
    71	  const currentCtx = gradeContext(current);
