    73	  async function submit() {
    74	    if (!target) return;
    75	    setSaving(true);
    76	    setError(null);
    77	    try {
    78	      const res = await fetch('/api/students/promotion', {
    79	        method: 'POST',
    80	        headers: { 'Content-Type': 'application/json' },
    81	        body: JSON.stringify({ to_type: target, reason: reason.trim() || undefined }),
    82	      });
