 import { computeTimeAdherence } from '@/lib/adherence';
 import { buildCrossRoleReportingPeriod } from '@/lib/reporting-period';
 import { todayKST } from '@/lib/daily-tasks-data';

 export async function GET(req: NextRequest) {
   try {
     const user = await requireUser();
     const url = new URL(req.url);
     const studentId = url.searchParams.get('id');

     if (!studentId) {
       return NextResponse.json({ error: '학생 ID 필수' }, { status: 400 });
     }

     // 학생 조회 + academy_id로 권한 검증
     // 주의: students 테이블에 dday 컬럼은 없음(수능일 기준 계산값). 존재 컬럼만 select.
     const { data: student, error: sErr } = await supabaseAdmin
       .from('students')
       .select(
         'id, name, type, exam_type, target_university, academy_id, anonymous_id, created_at'
       )
       .eq('id', studentId)
       .maybeSingle();

     if (sErr || !student) {
       throw new AuthError(404, '학생을 찾을 수 없습니다');
     }

     // D-day는 수능일 기준 계산 (students에 저장된 값이 아님).
     // Golden Rule #1: 하드코딩 날짜 금지 — 공식 시행일 테이블 + 학생 학년(type) 기준으로 계산.
     // (고1=2029·고2=2028·고3/N수=2027학년도 수능까지의 일수를 각각 정확히 산출)
     const ddayValue = getSuneungDdayForStudentType(
       (student.type ?? 'high3') as StudentType,
       new Date(),
     );

     if (!student.academy_id) {
       throw new AuthError(403, '학원에 소속되지 않은 학생');
     }

     // 본인이 이 학원의 admin인지 확인
     await assertAcademyAdmin(user.id, student.academy_id as string);

     // 학생 프로필
     const { data: profile } = await supabaseAdmin
       .from('student_profiles')
       .select('focus_minutes, math_subject, kor_subject, science_subject_1, science_subject_2, study_style, weakness, goal_university')
       .eq('student_id', studentId)
       .maybeSingle();

     // 최근 4개 KST 월~일 버킷. 같은 now를 주입해 주 경계 도중 호출 간 드리프트를 막는다.
     const now = new Date();
     const today = todayKST();
     const weekRanges = Array.from({ length: 4 }, (_, index) =>
       getWeekRange(index - 3, now),
     );
     const reportingStart = weekRanges[0].start;
     const reportingEnd = weekRanges[weekRanges.length - 1].end;

     const { data: tasks } = await supabaseAdmin
       .from('daily_tasks')
       .select('date, subject, completed, source, planned_min, actual_min, attended_min, camera_present_sec, attendance_source, attendance_status, timer_measured_min, camera_measured_sec')
       .eq('student_id', studentId)
       .gte('date', reportingStart)
       .lte('date', reportingEnd);

     // 주차별 집계 (월요일 시작 기준)
     const weeklyRates: Array<{ weekStart: string; rate: number; total: number; done: number }> = [];
     const tasksList = (tasks ?? []) as Array<{
       date: string;
       subject: string | null;
       source: string;
       completed: boolean;
       planned_min: number | null;
       actual_min: number | null;
       attended_min?: number | null;
       camera_present_sec?: number | null;
       attendance_source?: string | null;
       attendance_status?: string | null;
       timer_measured_min?: number | null;
       camera_measured_sec?: number | null;
     }>;

     for (const { start: weekStartStr, end: weekEnd } of weekRanges) {
       const weekPeriod = buildCrossRoleReportingPeriod(
         tasksList.filter((t) => t.date >= weekStartStr && t.date <= weekEnd),
       );
       const weekStats = weekPeriod.stats;
       weeklyRates.push({
         weekStart: weekStartStr,
         rate: weekStats.completionRate,
         total: weekStats.totalCount,
         done: weekStats.completedCount,
       });
     }

     // 이번 주 (현재 주) — 마지막 항목
     const thisWeek = weeklyRates[weeklyRates.length - 1] ?? {
       total: 0,
       done: 0,
       rate: 0,
     };

     // 월간 (4주 누적)
     const monthlyTotal = weeklyRates.reduce((s, w) => s + w.total, 0);
     const monthlyDone = weeklyRates.reduce((s, w) => s + w.done, 0);
     const monthlyRate =
