 type FreeSlot = { start: string; end: string; minutes: number };

 /** 빈 시간대(freeSlots) 중 [winStart,winEnd] 구간에서 dur분 빈 자리를 찾아 배치 (가장 이른 자리). */
 function placeMeal(
   freeSlots: FreeSlot[],
   winStart: string,
   winEnd: string,
   dur: number
 ): { start: string; end: string } | null {
   const wS = toMin(winStart);
   const wE = toMin(winEnd);
   for (const slot of [...freeSlots].sort((a, b) => toMin(a.start) - toMin(b.start))) {
     const s = Math.max(toMin(slot.start), wS);
     const e = Math.min(toMin(slot.end), wE);
     if (e - s >= dur) return { start: fromMin(s), end: fromMin(s + dur) };
   }
   return null;
 }

 /** freeSlots에서 blocks(식사 등) 구간을 빼고 남은 빈 시간대를 반환. */
 function subtractIntervals(slots: FreeSlot[], blocks: MealBreakRow[]): FreeSlot[] {
   const cuts = blocks.map((b) => [toMin(b.start_time), toMin(b.end_time)] as [number, number]);
   const out: FreeSlot[] = [];
   for (const s of slots) {
     let segs: Array<[number, number]> = [[toMin(s.start), toMin(s.end)]];
     for (const [cs, ce] of cuts) {
       const next: Array<[number, number]> = [];
       for (const [ss, se] of segs) {
         if (ce <= ss || cs >= se) { next.push([ss, se]); continue; }
         if (cs > ss) next.push([ss, Math.min(cs, se)]);
         if (ce < se) next.push([Math.max(ce, ss), se]);
       }
       segs = next;
     }
     for (const [ss, se] of segs) if (se > ss) out.push({ start: fromMin(ss), end: fromMin(se), minutes: se - ss });
   }
   return out;
 }

