   if (prints.length > 0) {
     lines.push('· 프린트:');
     for (const p of prints) {
       lines.push(`  - ${p.subject}: ${p.title}${p.unit ? ` · ${p.unit} 단원` : ''}${p.progress ? ` (현재 진도: ${p.progress})` : ''}${resourceParamSuffix(p)}`);
