+  ];
+
+  it('★ 다른 등급제 성적은 목표 갭을 계산하지 않는다', () => {
+    // 5등급제 3등급과 9등급제 목표 2등급을 빼면 "목표까지 1등급"이 나오는데,
+    // 두 숫자는 서로 다른 척도라 그 뺄셈은 의미가 없다 — 상담 결론이 틀어진다.
+    const out = buildSubjectGrades(crossRows, 2, 'g9');
+    const math = out.find((s) => s.subject === '수학')!;
+    expect(math.system).toBe('g5');
+    expect(math.crossSystem).toBe(true);
+    expect(math.gap).toBeNull();
+  });
+
+  it('같은 등급제 성적은 정상적으로 갭을 계산한다', () => {
+    const out = buildSubjectGrades(crossRows, 2, 'g9');
+    const eng = out.find((s) => s.subject === '영어')!;
+    expect(eng.crossSystem).toBe(false);
+    expect(eng.gap).toBe(1); // 3 - 2
+  });
+
+  it('★ 등급제가 같은 두 시험 사이에서만 추세를 낸다', () => {
+    // 같은 g5끼리는 비교 가능 — 2등급 → 3등급은 하락.
+    const out = buildSubjectGrades(crossRows, 2, 'g9');
+    expect(out.find((s) => s.subject === '수학')!.delta).toBe(1);
+  });
+
+  it('★ 등급제가 바뀐 구간에서는 추세를 내지 않는다', () => {
+    // 고2 5등급제 2등급 → 고3 9등급제 3등급. 숫자만 보면 "1등급 하락"이지만
+    // 척도가 달라 실제로는 향상일 수도 있다 — 모르는 것을 아는 척하지 않는다.
+    const mixed = [
+      { subject: '국어', grade: 2, exam_date: '2026-03-01', grade_system: 'g5' as const },
+      { subject: '국어', grade: 3, exam_date: '2026-09-01', grade_system: 'g9' as const },
+    ];
+    const out = buildSubjectGrades(mixed, 2, 'g9');
+    const kor = out.find((s) => s.subject === '국어')!;
+    expect(kor.system).toBe('g9');
+    expect(kor.crossSystem).toBe(false); // 최신은 현재 등급제와 같다
+    expect(kor.delta).toBeNull();        // 직전이 다른 등급제라 추세는 낼 수 없다
+    expect(kor.gap).toBe(1);             // 최신끼리는 비교 가능
+  });
+
+  it('각인이 없는 레거시 행은 현재 등급제로 폴백한다', () => {
+    const legacy = [{ subject: '수학', grade: 3, exam_date: '2026-05-01' }];
+    const out = buildSubjectGrades(legacy, 2, 'g9');
+    expect(out[0].system).toBe('g9');
+    expect(out[0].crossSystem).toBe(false);
+    expect(out[0].gap).toBe(1);
+  });
+});
