+    //    먼저 걸려서, stamp catch를 통째로 지워도 통과하는 **죽은 단언**이 된다.
+    //    반드시 각인 블록 안쪽 오프셋으로 환산해 비교한다.
+    const abortOffsetInBlock = stampBlock.indexOf('status: 500');
