   243	/**
   244	 * 과목별 최근 성적 델타(직전등급 - 최신등급, 양수=향상)를 baseSubject 키로 집계한다.
   245	 * 리포트 카드와 같은 규칙: 같은 report_type끼리 최신 2건 비교. 실패 시 빈 맵(근거 생략).
   246	 */
   247	async function loadGradeDeltas(
   248	  studentId: string,
   249	  sci1: string | null,
   250	  sci2: string | null,
   251	): Promise<Map<string, number>> {
   252	  const out = new Map<string, number>();
   253	  try {
   254	    const grades = await loadLatestGradesPerGroup<RecentGrade>(async (from, to) => {
   255	      const { data, error } = await supabaseAdmin
   256	        .from('grades')
   257	        .select('id, exam_name, subject, grade, report_type, exam_date')
   258	        .eq('student_id', studentId)
   259	        .not('grade', 'is', null)
   260	        .order('exam_date', { ascending: false })
   261	        .order('id', { ascending: false })
   262	        .range(from, to);
   263	      if (error) throw error;
   264	      return (data ?? []) as RecentGrade[];
   265	    });
   266	
   267	    // 과목+종류별 최신 2건 → 델타. 여러 종류가 있으면 절대 변화가 큰 쪽을 대표로.
   268	    const groups = new Map<string, RecentGrade[]>();
   269	    for (const g of grades) {
   270	      if (g.grade == null || !isAcademyGradeReportType(g.report_type)) continue;
   271	      const real = resolveSlotSubject(g.subject, sci1, sci2);
   272	      const key = `${baseSubject(real)}|${g.report_type}`;
   273	      const arr = groups.get(key) ?? [];
   274	      arr.push(g);
   275	      groups.set(key, arr);
   276	    }
   277	    for (const [key, arr] of groups) {
   278	      const base = key.split('|')[0];
   279	      const latest = arr[0]?.grade;
   280	      const prev = arr[1]?.grade;
   281	      if (latest == null || prev == null) continue;
   282	      const delta = prev - latest; // 등급 낮을수록 좋음 → 양수=향상
   283	      const cur = out.get(base);
   284	      if (cur === undefined || Math.abs(delta) > Math.abs(cur)) out.set(base, delta);
   285	    }
   286	  } catch (e) {
   287	    console.error('[subject-coaching] 성적 델타 조회 실패(근거 생략):', e);
   288	  }
   289	  return out;
   290	}

