import { redirect } from 'next/navigation';
import { getAuthedUser } from '@/lib/auth';
import { supabaseAdmin } from '@/lib/supabase';
import { ROLE_DEFAULT_PATH, type UserRole } from '@/types';
import OnboardingClient from './OnboardingClient';

export default async function OnboardingPage() {
  const user = await getAuthedUser();

  if (!user) redirect('/login?redirect=/onboarding');

  // ⭐ role 가드 — 학생만 온보딩 진행
  const { data: userRow } = await supabaseAdmin
    .from('users')
    .select('role')
    .eq('id', user.id)
    .maybeSingle();

  const role = (userRow?.role as UserRole | undefined) ?? 'student';
  if (role !== 'student') {
    redirect(ROLE_DEFAULT_PATH[role]);
  }

  // 이미 온보딩 완료했는지 확인 (supabaseAdmin로 RLS 우회 — 본인 user_id 명시적 필터라 보안 OK)
  const { data: student } = await supabaseAdmin
    .from('students')
    .select('id')
    .eq('user_id', user.id)
    .maybeSingle();

  if (student) redirect('/today');

  // 회원가입 때 입력한 이름을 온보딩 STEP0에 prefill — 회원가입 폼에서 받은 이름이
  // users 테이블엔 저장되지 않고 auth user_metadata(full_name)에만 남아있어 여기서 가져온다.
  // (같은 이름을 두 번 입력하게 하던 문제 수정)
  const { data: authUser } = await supabaseAdmin.auth.admin.getUserById(user.id);
  const defaultName =
    (authUser?.user?.user_metadata as { full_name?: string } | undefined)?.full_name ?? '';

  return <OnboardingClient userId={user.id} userEmail={user.email ?? ''} defaultName={defaultName} />;
}
