     8	//     추론하면 학평의 석차를 내신으로 오분류하거나, 과거 내신을 모의고사에 섞을 수 있다.
     9	// ══════════════════════════════════════════════════════════════
    10	
    11	import { isAcademyGradeReportType } from '@/lib/academy-grade-report-type';
    12	
    13	export type GradeComparisonType = 'mock' | 'naesin' | 'suneung';
    14	
    15	/** 비교에 필요한 성적행 최소 형태(/api/grades 응답의 부분집합). */
    16	export interface GradeComparisonRow {
    17	  subject: string;
    18	  grade: number | null;
    19	  exam_name: string;
    20	  exam_date: string; // YYYY-MM-DD
    21	  report_type?: unknown;
    22	  achievement?: string | null;
    23	  converted_score?: number | null;
    24	  rank?: number | null;
    25	  percentile?: number | null;
    26	  standard_score?: number | null;
    27	}
    28	
    29	export interface GradeTrendPoint {
    30	  examName: string;
    31	  date: string; // YYYY-MM-DD
    32	  grade: number;
    33	}
    34	
    35	export interface SubjectTrend {
    36	  subject: string;
    37	  /** 날짜 오름차순 — 왼쪽이 과거, 오른쪽이 최신. */
    38	  points: GradeTrendPoint[];
    39	  /** 가장 최근 등급. */
    40	  latest: number;
    41	  /** 최신 − 직전 등급. 음수 = 등급 숫자 하락 = 개선. 점이 1개뿐이면 null. */
    42	  delta: number | null;
    43	}
    44	
    45	export interface GradeTrendGroup {
    46	  type: GradeComparisonType;
    47	  subjects: SubjectTrend[];
    48	}
    49	
    50	/** 성적행을 비교 축(내신/모의)으로 분류한다. 종류를 확인할 수 없으면 비교하지 않는다. */
    51	export function resolveComparisonType(row: GradeComparisonRow): GradeComparisonType | null {
    52	  if (!isAcademyGradeReportType(row.report_type)) return null;
    53	  return row.report_type;
    54	}
    55	
    56	/**
    57	 * 성적행을 타입별·과목별 추이로 묶는다.
    58	 * - 등급(grade)이 없는 행은 제외(추이에 그릴 점이 없음).
    59	 * - 각 과목 점은 날짜 오름차순.
    60	 * - 데이터가 하나도 없는 타입 그룹은 배열에서 생략.
    61	 */
    62	export function buildGradeTrendGroups(rows: readonly GradeComparisonRow[]): GradeTrendGroup[] {
    63	  const byType: Record<GradeComparisonType, Map<string, GradeTrendPoint[]>> = {
    64	    mock: new Map(),
    65	    naesin: new Map(),
    66	    suneung: new Map(),
    67	  };
    68	
    69	  for (const r of rows) {
    70	    if (r.grade == null) continue;
    71	    const type = resolveComparisonType(r);
    72	    if (!type) continue;
    73	    const bucket = byType[type];
    74	    const points = bucket.get(r.subject) ?? [];
    75	    points.push({ examName: r.exam_name, date: r.exam_date, grade: r.grade });
    76	    bucket.set(r.subject, points);
    77	  }
    78	
    79	  const groups: GradeTrendGroup[] = [];
    80	  for (const type of ['mock', 'naesin', 'suneung'] as const) {
    81	    const bucket = byType[type];
    82	    if (bucket.size === 0) continue;
    83	
    84	    const subjects: SubjectTrend[] = [];
    85	    for (const [subject, rawPoints] of bucket) {
    86	      const points = [...rawPoints].sort((a, b) => (a.date < b.date ? -1 : a.date > b.date ? 1 : 0));
    87	      const latest = points[points.length - 1].grade;
    88	      const delta = points.length >= 2 ? latest - points[points.length - 2].grade : null;
    89	      subjects.push({ subject, points, latest, delta });
    90	    }
    91	    // 추이(2점 이상)가 있는 과목을 위로, 그다음 최신 등급이 좋은(숫자 작은) 순, 과목명 순.
    92	    subjects.sort((a, b) => {
    93	      const aTrend = a.points.length >= 2 ? 1 : 0;
    94	      const bTrend = b.points.length >= 2 ? 1 : 0;
    95	      if (aTrend !== bTrend) return bTrend - aTrend;
    96	      if (a.latest !== b.latest) return a.latest - b.latest;
    97	      return a.subject.localeCompare(b.subject);
    98	    });
    99	
   100	    groups.push({ type, subjects });
   101	  }
   102	
   103	  return groups;
   104	}

